///////// 1. 변수 및 선언 영역 /////////
scwin.gProcType = "N"; // 디폴트는 신규모드
scwin.vData1 = "E";
scwin.vData2 = "E";
scwin.vData3 = "E";
scwin.gIsurCd;
scwin.gEmpNo = js_emp_no;

/**
 * @method
