};

/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    scwin.gIsurCd = scwin.gIsurCd = $c.stf.getQuery(frame.srcUrl, "ISUR_CD");
    const gComNm = $c.stf.getQuery(frame.srcUrl, "COM_ABBRV");
    if ($c.ut.trim(scwin.gIsurCd).length === 5) {
        // alert(gIsurCd);
        txb_ISUR_CD.setValue(scwin.gIsurCd);
        txb_COM_NM.setValue(gComNm);
        scwin.gProcType = "M"; // 수정모드
        scwin.initSearch();
    }
};

/**
 * @method
 * @name setCode
 * @description 미제출사유  셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    // 미제출사유  셋팅
    const sbmOptions = {
        id : "sbm_dts_nsubmitRsn1",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_nsubmitRsn1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_nsubmitRsn2",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_nsubmitRsn2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_nsubmitRsn3",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_nsubmitRsn3=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
