};X < !조건체크--;
사용자;
클릭-- > async function() {
    // 법인코드 자리수 체크
    if (txb_ISUR_CD.getValue().length !== 5) {
        await $c.win.alert("회사코드 5자리를 올바르게 입력하십시오.");
        txb_ISUR_CD.focus();
        return;
    }
} < !조회--;
사용자;
클릭-- > async function() {

    //  데이타 조회
    const sbmOptions = {
        id : "sbm_dts_nsubmit_info",
        action : "/SubmitStatus.do",
        ref : "",
        target : "dts_nsubmit_info=body.content",
        isProcessMsg : false
