    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name chkValueExist
 * @description chk Value Exist 처리
 * @param {*} obj1 obj1
 * @param {*} obj2 obj2
 * @param {*} obj3 obj3
 * @returns {void}
 * @hidden N
 */
scwin.chkValueExist = function(obj1, obj2, obj3) {
    let vValCnt = 0;
    if (obj1.getValue() === "") {
        vValCnt = vValCnt + 1;
    }
    if (obj2.getValue() === "") {
        vValCnt = vValCnt + 3;
    }
    if (obj3.getValue() === "") {
        vValCnt = vValCnt + 5;
    }
    return vValCnt;
};

/**
 * @method
 * @name checkValue
 * @description check Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValue = async function() {
    let vIsurCd = txb_isurcd.getValue();
    if (vIsurCd === "") {
        await $c.win.alert("회사코드로  내역조회후에 입력처리가 가능합니다.");
        txb_ISUR_CD.focus();
        return false;
    }

    // 신규입력일때
    if (scwin.gProcType === "N") {
        // 한개이상 데이터 입력 필요.
        if (edt_design_dd1.getValue() === "" && edt_end_dd1.getValue() === "" && cmb_nsubmit_rsn1.getValue() === "" &&
            edt_design_dd2.getValue() === "" && edt_end_dd2.getValue() === "" && cmb_nsubmit_rsn2.getValue() === "" &&
            edt_design_dd3.getValue() === "" && edt_end_dd3.getValue() === "" && cmb_nsubmit_rsn3.getValue() === "") {
            await $c.win.alert("한 건이상의 데이타를 입력하셔야 합니다.");
            edt_design_dd1.focus();
            return false;
        }
        let vValStat = scwin.chkValueExist(edt_design_dd1, edt_end_dd1, cmb_nsubmit_rsn1);
        if (vValStat === 9) {
            await $c.win.alert("한 건이상의 데이타를 입력하셔야 합니다.");
            edt_design_dd1.focus();
            return false;
        } else if (vValStat === 1 || vValStat === 4 || vValStat === 6) {
            await $c.win.alert("지정일1을  입력하셔야 합니다.");
            edt_design_dd1.focus();
            return false;
        } else if (vValStat === 3 || vValStat === 8) {
            await $c.win.alert("만료일1을  입력하셔야 합니다.");
            edt_end_dd1.focus();
            return false;
        } else if (vValStat === 5) {
            await $c.win.alert("사유1을  입력하셔야 합니다.");
            cmb_nsubmit_rsn1.focus();
            return false;
        } else if (vValStat === 0) {
            scwin.vData1 = "I"; //

        }
        vValStat = scwin.chkValueExist(edt_design_dd2, edt_end_dd2, cmb_nsubmit_rsn2);
        if (vValStat === 1 || vValStat === 4 || vValStat === 6) {
            await $c.win.alert("지정일2를  입력하셔야 합니다.");
            edt_design_dd2.focus();
            return false;
        } else if (vValStat === 3 || vValStat === 8) {
            await $c.win.alert("만료일2를  입력하셔야 합니다.");
            edt_end_dd2.focus();
            return false;
        } else if (vValStat === 5) {
            await $c.win.alert("사유2를  입력하셔야 합니다.");
            cmb_nsubmit_rsn2.focus();
            return false;
        } else if (vValStat === 0) {
            scwin.vData2 = "I"; //

        }
        vValStat = scwin.chkValueExist(edt_design_dd3, edt_end_dd3, cmb_nsubmit_rsn3);
        if (vValStat === 1 || vValStat === 4 || vValStat === 6) {
            await $c.win.alert("지정일3을  입력하셔야 합니다.");
            edt_design_dd3.focus();
            return false;
        } else if (vValStat === 3 || vValStat === 8) {
            await $c.win.alert("만료일3을  입력하셔야 합니다.");
            edt_end_dd3.focus();
            return false;
        } else if (vValStat === 5) {
            await $c.win.alert("사유3을  입력하셔야 합니다.");
            cmb_nsubmit_rsn3.focus();
            return false;
        } else if (vValStat === 0) {
            scwin.vData3 = "I"; //

        }
    } else {
        // 첫번째
        if (edt_design_dd1_old.getValue() === edt_design_dd1.getValue() &&
            edt_end_dd1_old.getValue() === edt_end_dd1.getValue() &&
            txt_nsubmit_rsn1_old.getValue() === cmb_nsubmit_rsn1.getValue()) {
            scwin.vData1 = "E"; // Equal -> DB에 아무런것도 하지 않음

        } else {
            if (edt_design_dd1_old.getValue() !== "" &&
                edt_design_dd1.getValue() === "" &&
                edt_end_dd1.getValue() === "" &&
                cmb_nsubmit_rsn1.getValue() === "") {
                scwin.vData1 = "D"; // delete

            } else {
                let vValStat = scwin.chkValueExist(edt_design_dd1, edt_end_dd1, cmb_nsubmit_rsn1);
                if (vValStat === 9) {
                    await $c.win.alert("한 건이상의 데이타를 입력하셔야 합니다.");
                    edt_design_dd1.focus();
                    return false;
                } else if (vValStat === 1 || vValStat === 4 || vValStat === 6) {
                    await $c.win.alert("지정일1을  입력하셔야 합니다.");
                    edt_design_dd1.focus();
                    return false;
                } else if (vValStat === 3 || vValStat === 8) {
                    await $c.win.alert("만료일1을  입력하셔야 합니다.");
                    edt_end_dd1.focus();
                    return false;
                } else if (vValStat === 5) {
                    await $c.win.alert("사유1을  입력하셔야 합니다.");
                    cmb_nsubmit_rsn1.focus();
                    return false;
                } else if (vValStat === 0) {
                    scwin.vData1 = "U"; // update

                }
            }
        }

        // 두번째
        if (edt_design_dd2_old.getValue() === edt_design_dd2.getValue() &&
            edt_end_dd2_old.getValue() === edt_end_dd2.getValue() &&
            txt_nsubmit_rsn2_old.getValue() === cmb_nsubmit_rsn2.getValue()) {
            scwin.vData2 = "E"; // Equal -> DB에 아무런것도 하지 않음

        } else {
            if (edt_design_dd2_old.getValue() !== "" &&
                edt_design_dd2.getValue() === "" &&
                edt_end_dd2.getValue() === "" &&
                cmb_nsubmit_rsn2.getValue() === "") {
                scwin.vData2 = "D"; // delete

            } else {
                let vValStat = scwin.chkValueExist(edt_design_dd2, edt_end_dd2, cmb_nsubmit_rsn2);
                if (vValStat === 9) {
                    await $c.win.alert("한 건이상의 데이타를 입력하셔야 합니다.");
                    edt_design_dd2.focus();
                    return false;
                } else if (vValStat === 1 || vValStat === 4 || vValStat === 6) {
                    await $c.win.alert("지정일2를  입력하셔야 합니다.");
                    edt_design_dd2.focus();
                    return false;
                } else if (vValStat === 3 || vValStat === 8) {
                    await $c.win.alert("만료일2를  입력하셔야 합니다.");
                    edt_end_dd2.focus();
                    return false;
                } else if (vValStat === 5) {
                    await $c.win.alert("사유2를  입력하셔야 합니다.");
                    cmb_nsubmit_rsn2.focus();
                    return false;
                } else if (vValStat === 0) {
                    scwin.vData2 = "U"; // update

                }
            }
        }

        // 세번째
        if (edt_design_dd3_old.getValue() === edt_design_dd3.getValue() &&
            edt_end_dd3_old.getValue() === edt_end_dd3.getValue() &&
            txt_nsubmit_rsn3_old.getValue() === cmb_nsubmit_rsn3.getValue()) {
            scwin.vData3 = "E"; // Equal -> DB에 아무런것도 하지 않음

        } else {
            if (edt_design_dd3_old.getValue() !== "" &&
                edt_design_dd3.getValue() === "" &&
                edt_end_dd3.getValue() === "" &&
                cmb_nsubmit_rsn3.getValue() === "") {
                scwin.vData3 = "D"; // delete

            } else {
                let vValStat = scwin.chkValueExist(edt_design_dd3, edt_end_dd3, cmb_nsubmit_rsn3);
                if (vValStat === 9) {
                    await $c.win.alert("한 건이상의 데이타를 입력하셔야 합니다.");
                    edt_design_dd3.focus();
                    return false;
                } else if (vValStat === 1 || vValStat === 4 || vValStat === 6) {
                    await $c.win.alert("지정일3을  입력하셔야 합니다.");
                    edt_design_dd3.focus();
                    return false;
                } else if (vValStat === 3 || vValStat === 8) {
                    await $c.win.alert("만료일3을  입력하셔야 합니다.");
                    edt_end_dd3.focus();
                    return false;
                } else if (vValStat === 5) {
                    await $c.win.alert("사유3을  입력하셔야 합니다.");
                    cmb_nsubmit_rsn3.focus();
                    return false;
                } else if (vValStat === 0) {
                    scwin.vData3 = "U"; // update

                }
            }
        }
    }
    return true;
};

/**
 * @method
 * @name insert
 * @description 미제출정보 등록 & 수정 & 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function() {
    if (await scwin.checkValue() === false) {
        return;
    }

    // alert(     vData1 +", "+  vData2 +", "+ vData3 );

    dts_Nsubmit_Input.insertRow();
    dts_Nsubmit_Input.setCellData(1, "ISUR_CD", txb_isurcd.getValue());
    dts_Nsubmit_Input.setCellData(1, "DESIGN_DD1", edt_design_dd1.getValue());
    dts_Nsubmit_Input.setCellData(1, "END_DD1", edt_end_dd1.getValue());
    dts_Nsubmit_Input.setCellData(1, "NSUBMIT_RSN_CD1", cmb_nsubmit_rsn1.getValue());
    dts_Nsubmit_Input.setCellData(1, "PROC_TYPE1", scwin.vData1);
    dts_Nsubmit_Input.setCellData(1, "DESIGN_DD2", edt_design_dd2.getValue());
    dts_Nsubmit_Input.setCellData(1, "END_DD2", edt_end_dd2.getValue());
    dts_Nsubmit_Input.setCellData(1, "NSUBMIT_RSN_CD2", cmb_nsubmit_rsn2.getValue());
    dts_Nsubmit_Input.setCellData(1, "PROC_TYPE2", scwin.vData2);
    dts_Nsubmit_Input.setCellData(1, "DESIGN_DD3", edt_design_dd3.getValue());
    dts_Nsubmit_Input.setCellData(1, "END_DD3", edt_end_dd3.getValue());
    dts_Nsubmit_Input.setCellData(1, "NSUBMIT_RSN_CD3", cmb_nsubmit_rsn3.getValue());
    dts_Nsubmit_Input.setCellData(1, "PROC_TYPE3", scwin.vData3);
    dts_Nsubmit_Input.setCellData(1, "EMP_NO", scwin.gEmpNo);
    if (scwin.vData1 === "U") {
        dts_Nsubmit_Input.setCellData(1, "DESIGN_DD1_OLD", edt_design_dd1_old.getValue());
        dts_Nsubmit_Input.setCellData(1, "END_DD1_OLD", edt_end_dd1_old.getValue());
        dts_Nsubmit_Input.setCellData(1, "NSUBMIT_RSN_CD1_OLD", txt_nsubmit_rsn1_old.getValue());
    }
    if (scwin.vData2 === "U") {
        dts_Nsubmit_Input.setCellData(1, "DESIGN_DD2_OLD", edt_design_dd2_old.getValue());
        dts_Nsubmit_Input.setCellData(1, "END_DD2_OLD", edt_end_dd2_old.getValue());
        dts_Nsubmit_Input.setCellData(1, "NSUBMIT_RSN_CD2_OLD", txt_nsubmit_rsn2_old.getValue());
    }
    if (scwin.vData3 === "U") {
        dts_Nsubmit_Input.setCellData(1, "DESIGN_DD3_OLD", edt_design_dd3_old.getValue());
        dts_Nsubmit_Input.setCellData(1, "END_DD3_OLD", edt_end_dd3_old.getValue());
        dts_Nsubmit_Input.setCellData(1, "NSUBMIT_RSN_CD3_OLD", txt_nsubmit_rsn3_old.getValue());
    }

    // alert(dts_Nsubmit_Input.text);
    let vAnswer = confirm('저장처리 하시겠습니까?');
    if (vAnswer === true) {
        trs_Nsubmit_Input.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Nsubmit_Input",
            action : "/SubmitStatus.do",
            ref : "dts_Nsubmit_Input",
            target : "trs_Nsubmit_Input=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    let vIsurCd = txb_isurcd.getValue();
    if (vIsurCd === "") {
        await $c.win.alert("회사코드로  내역조회후에 삭제처리가 가능합니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    dts_Nsubmit_Delete.insertRow();
    dts_Nsubmit_Delete.setCellData(1, "ISUR_CD", txb_isurcd.getValue());

    // alert(dts_Nsubmit_Input.text);
    let vAnswer = confirm('전체 정보를 삭제처리 하시겠습니까?');
    if (vAnswer === true) {
        trs_Nsubmit_Delete.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Nsubmit_Delete",
            action : "/SubmitStatus.do",
            ref : "dts_Nsubmit_Delete",
            target : "trs_Nsubmit_Delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

