/**
 * @method
 * @name dts_nsubmit_info_OnLoadCompleted
 * @description dts_nsubmit_info 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_nsubmit_info_OnLoadCompleted = function(rowcount) {
    edt_design_dd1_old.setValue(dts_nsubmit_info.getCellData(1, "DESIGN_DD1"));
    edt_design_dd2_old.setValue(dts_nsubmit_info.getCellData(1, "DESIGN_DD2"));
    edt_design_dd3_old.setValue(dts_nsubmit_info.getCellData(1, "DESIGN_DD3"));
    edt_end_dd1_old.setValue(dts_nsubmit_info.getCellData(1, "END_DD1"));
    edt_end_dd2_old.setValue(dts_nsubmit_info.getCellData(1, "END_DD2"));
    edt_end_dd3_old.setValue(dts_nsubmit_info.getCellData(1, "END_DD3"));
    txt_nsubmit_rsn1_old.setValue(dts_nsubmit_info.getCellData(1, "NSUBMIT_RSN_CD1"));
    txt_nsubmit_rsn2_old.setValue(dts_nsubmit_info.getCellData(1, "NSUBMIT_RSN_CD2"));
    txt_nsubmit_rsn3_old.setValue(dts_nsubmit_info.getCellData(1, "NSUBMIT_RSN_CD3"));
    if (dts_nsubmit_info.getCellData(1, "DESIGN_DD1") !== '') {
        scwin.gProcType = 'M'; // 조회 후 1건 이상일때

    }
};

