/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw !== "" && foColum === "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

        else return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    panel_hidden.hide(); // 히든처리!

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    await scwin.setCode();
    scwin.getParentValue();

    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_Nsubmit_Input",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Nsubmit_Input=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_Nsubmit_Delete",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Nsubmit_Delete=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    // fn_InitSearch();

};
